   322→    let DataColumnSidecar {
   323→        kzg_commitments,
   324→        signed_block_header,
   325→        kzg_commitments_inclusion_proof,
   326→        ..
   327→    } = data_column_sidecar;
   328→
   329→    get_data_column_sidecars(
   330→        *signed_block_header,
   331→        kzg_commitments,
   332→        *kzg_commitments_inclusion_proof,
   333→        cells_and_kzg_proofs,
