   336→
   337→pub fn try_convert_to_cells_and_kzg_proofs<P: Preset>(
   338→    blobs: &[Blob<P>],
   339→    cell_proofs: &[KzgProof],
   340→    backend: KzgBackend,
   341→) -> Result<Vec<CellsAndKzgProofs<P>>> {
   342→    let expected_proofs_length = blobs.len() * P::CellsPerExtBlob::USIZE;
   343→    ensure!(
   344→        cell_proofs.len() == expected_proofs_length,
   345→        Error::InvalidCellsProofsLength {
   346→            expected: expected_proofs_length,
   347→            proofs_length: cell_proofs.len(),
   348→        }
   349→    );
   350→
   351→    blobs
   352→        .par_iter()
   353→        .enumerate()
   354→        .map(|(i, blob)| {
   355→            compute_cells::<P>(blob, backend).and_then(|cells| {
   356→                let start = P::CellsPerExtBlob::USIZE.saturating_mul(i);
   357→                let end = P::CellsPerExtBlob::USIZE.saturating_add(start);
   358→                ContiguousVector::try_from_iter(cell_proofs[start..end].iter().copied())
   359→                    .map(|proofs| (cells, proofs))
   360→                    .map_err(Into::into)
   361→            })
   362→        })
   363→        .collect::<Result<Vec<_>>>()
   364→}
   365→
   366→pub fn construct_cells_and_kzg_proofs<P: Preset>(
   367→    full_matrix: Vec<MatrixEntry<P>>,
   368→) -> Result<Vec<CellsAndKzgProofs<P>>> {
   369→    // Group and sort the matrix entries by blob index
   370→    let mut full_matrix_map = BTreeMap::new();
   371→    for matrix in full_matrix {
   372→        full_matrix_map
   373→            .entry(matrix.row_index)
   374→            .or_insert(Vec::new())
   375→            .push(matrix);
   376→    }
   377→
   378→    let mut result = Vec::new();
   379→    for entries in full_matrix_map.into_values() {
   380→        let (cells, proofs): (Vec<_>, Vec<_>) =
   381→            entries.into_iter().map(|e| (e.cell, e.kzg_proof)).unzip();
   382→
   383→        let cells = ContiguousVector::try_from_iter(cells.into_iter())?;
   384→        let proofs = ContiguousVector::try_from_iter(proofs.into_iter())?;
   385→        result.push((cells, proofs));
   386→    }
   387→
   388→    Ok(result)
   389→}
   390→
   391→pub fn get_validator_custody_requirement<P: Preset>(
   392→    last_finalized_state: &impl BeaconState<P>,
   393→    validator_indices: &HashSet<ValidatorIndex>,
   394→    config: &Config,
   395→) -> u64 {
   396→    let total_node_balance = validator_indices
   397→        .iter()
   398→        .map(|index| {
   399→            last_finalized_state
   400→                .validators()
   401→                .get(*index)
   402→                .map(|validator| validator.effective_balance)
   403→        })
   404→        .process_results(|iter| iter.sum::<Gwei>())
   405→        .unwrap_or(0);
   406→
   407→    let count = total_node_balance.saturating_div(config.balance_per_additional_custody_group);
   408→
   409→    count
   410→        .max(config.validator_custody_requirement)
   411→        .min(config.number_of_custody_groups)
   412→}
   413→
   414→fn construct_full_matrix<P: Preset>(
   415→    cells_and_kzg_proofs: Vec<CellsAndKzgProofs<P>>,
   416→) -> Vec<MatrixEntry<P>> {
   417→    cells_and_kzg_proofs
   418→        .into_iter()
   419→        .enumerate()
   420→        .flat_map(|(blob_index, (cells, proofs))| {
   421→            cells
   422→                .into_iter()
   423→                .zip(proofs)
   424→                .enumerate()
   425→                .map(move |(cell_index, (cell, kzg_proof))| MatrixEntry {
   426→                    cell,
   427→                    kzg_proof,
   428→                    row_index: blob_index as u64,
   429→                    column_index: cell_index as u64,
   430→                })
   431→        })
   432→        .collect()
   433→}
